//	/** Get the extended whitespace length. Used with `char_is_space_ext`. */
//go:nocheckptr
func ext_space_len(tls *libc.TLS, cur uintptr) (r Tusize) {
	var uni Tu32
	_ = uni
	if libc.Int32FromUint8(*(*Tu8)(unsafe.Pointer(cur))) < int32(0x80) {
		return uint64(1)
	} else {
		if libc.Int32FromUint16(byte_load_2(tls, cur)) == libc.Int32FromUint16(byte_load_2(tls, __ccgo_ts+243)) {
			return uint64(2)
		} else {
			if libc.Int32FromUint16(byte_load_2(tls, cur)) == libc.Int32FromUint16(byte_load_2(tls, __ccgo_ts+246)) {
				if libc.Int32FromUint8(*(*Tu8)(unsafe.Pointer(cur + 2))) >= int32(0x80) && libc.Int32FromUint8(*(*Tu8)(unsafe.Pointer(cur + 2))) <= int32(0x8A) {
					return uint64(3)
				}
				if libc.Int32FromUint8(*(*Tu8)(unsafe.Pointer(cur + 2))) == int32(0xA8) || libc.Int32FromUint8(*(*Tu8)(unsafe.Pointer(cur + 2))) == int32(0xA9) || libc.Int32FromUint8(*(*Tu8)(unsafe.Pointer(cur + 2))) == int32(0xAF) {
					return uint64(3)
				}
			} else {
				uni = byte_load_3(tls, cur)
				if uni == byte_load_3(tls, __ccgo_ts+249) || uni == byte_load_3(tls, __ccgo_ts+253) || uni == byte_load_3(tls, __ccgo_ts+257) || uni == byte_load_3(tls, __ccgo_ts+223) {
					return uint64(3)
				}
			}
		}
	}
	return uint64(0)
}

