// C documentation
//
//	/** Load 4 hex characters to `u16`, return true on valid input. */
//go:nocheckptr
func hex_load_4(tls *libc.TLS, src uintptr, dst uintptr) (r uint8) {
	var c0, c1, c2, c3, t0, t1 Tu16
	_, _, _, _, _, _ = c0, c1, c2, c3, t0, t1
	c0 = uint16(hex_conv_table[*(*Tu8)(unsafe.Pointer(src))])
	c1 = uint16(hex_conv_table[*(*Tu8)(unsafe.Pointer(src + 1))])
	c2 = uint16(hex_conv_table[*(*Tu8)(unsafe.Pointer(src + 2))])
	c3 = uint16(hex_conv_table[*(*Tu8)(unsafe.Pointer(src + 3))])
	t0 = libc.Uint16FromInt32(libc.Int32FromUint16(c0)<<libc.Int32FromInt32(8) | libc.Int32FromUint16(c2))
	t1 = libc.Uint16FromInt32(libc.Int32FromUint16(c1)<<libc.Int32FromInt32(8) | libc.Int32FromUint16(c3))
	*(*Tu16)(unsafe.Pointer(dst)) = libc.Uint16FromInt32(libc.Int32FromUint16(t0)<<libc.Int32FromInt32(4) | libc.Int32FromUint16(t1))
	return libc.BoolUint8((libc.Int32FromUint16(t0)|libc.Int32FromUint16(t1))&libc.Int32FromUint16(libc.Uint16FromInt32(0xF0F0)) == 0)
}

// C documentation
//
//	/** Load 2 hex characters to `u8`, return true on valid input. */
//go:nocheckptr
func hex_load_2(tls *libc.TLS, src uintptr, dst uintptr) (r uint8) {
	var c0, c1 Tu8
	_, _ = c0, c1
	c0 = hex_conv_table[*(*Tu8)(unsafe.Pointer(src))]
	c1 = hex_conv_table[*(*Tu8)(unsafe.Pointer(src + 1))]
	*(*Tu8)(unsafe.Pointer(dst)) = libc.Uint8FromInt32(libc.Int32FromUint8(c0)<<libc.Int32FromInt32(4) | libc.Int32FromUint8(c1))
	return libc.BoolUint8((libc.Int32FromUint8(c0)|libc.Int32FromUint8(c1))&int32(0xF0) == 0)
}

// C documentation
//
//	/** Match a hexadecimal numeric character: [0-9a-fA-F]. */
func char_is_hex(tls *libc.TLS, c Tu8) (r uint8) {
	return libc.BoolUint8(libc.Int32FromUint8(hex_conv_table[c]) != int32(0xF0))
}

/*==============================================================================
 * MARK: - UTF8 Validation (Private)
 * Each Unicode code point is encoded using 1 to 4 bytes in UTF-8.
 * Validation is performed using a 4-byte mask and pattern-based approach,
 * which requires the input data to be padded with four zero bytes at the end.
 *============================================================================*/

/* Macro for concatenating four u8 into a u32 and keeping the byte order. */

// C documentation
//
//	/*
//	 1-byte sequence (U+0000 to U+007F)
//	 bit min        [.......0] (U+0000)
//	 bit max        [.1111111] (U+007F)
//	 bit mask       [x.......] (80)
//	 bit pattern    [0.......] (00)
//	 */
var utf8_seq_b1_mask = uint32(0x00000080)

var utf8_seq_b1_patt = uint32(0x00000000)

// C documentation
//
//	/*
//	 2-byte sequence (U+0080 to U+07FF)
//	 bit min        [......10 ..000000] (U+0080)
//	 bit max        [...11111 ..111111] (U+07FF)
//	 bit mask       [xxx..... xx......] (E0 C0)
//	 bit pattern    [110..... 10......] (C0 80)
//	 bit require    [...xxxx. ........] (1E 00)
//	 */
var utf8_seq_b2_mask = uint32(0x0000C0E0)

var utf8_seq_b2_patt = uint32(0x000080C0)

var utf8_seq_b2_requ = uint32(0x0000001E)

// C documentation
//
//	/*
//	 3-byte sequence (U+0800 to U+FFFF)
//	 bit min        [........ ..100000 ..000000] (U+0800)
//	 bit max        [....1111 ..111111 ..111111] (U+FFFF)
//	 bit mask       [xxxx.... xx...... xx......] (F0 C0 C0)
//	 bit pattern    [1110.... 10...... 10......] (E0 80 80)
//	 bit require    [....xxxx ..x..... ........] (0F 20 00)
//
//	 3-byte invalid sequence, reserved for surrogate halves (U+D800 to U+DFFF)
//	 bit min        [....1101 ..100000 ..000000] (U+D800)
//	 bit max        [....1101 ..111111 ..111111] (U+DFFF)
//	 bit mask       [....xxxx ..x..... ........] (0F 20 00)
//	 bit pattern    [....1101 ..1..... ........] (0D 20 00)
//	 */
var utf8_seq_b3_mask = uint32(0x00C0C0F0)

var utf8_seq_b3_patt = uint32(0x008080E0)

var utf8_seq_b3_requ = uint32(0x0000200F)

var utf8_seq_b3_erro = uint32(0x0000200D)

// C documentation
//
//	/*
//	 4-byte sequence (U+10000 to U+10FFFF)
//	 bit min        [........ ...10000 ..000000 ..000000] (U+10000)
//	 bit max        [.....100 ..001111 ..111111 ..111111] (U+10FFFF)
//	 bit mask       [xxxxx... xx...... xx...... xx......] (F8 C0 C0 C0)
//	 bit pattern    [11110... 10...... 10...... 10......] (F0 80 80 80)
//	 bit require    [.....xxx ..xx.... ........ ........] (07 30 00 00)
//	 bit require 1  [.....x.. ........ ........ ........] (04 00 00 00)
//	 bit require 2  [......xx ..xx.... ........ ........] (03 30 00 00)
//	 */
var utf8_seq_b4_mask = uint32(0xC0C0C0F8)

var utf8_seq_b4_patt = uint32(0x808080F0)

var utf8_seq_b4_requ = uint32(0x00003007)

var utf8_seq_b4_req1 = uint32(0x00000004)

var utf8_seq_b4_req2 = uint32(0x00003003)

