// C documentation
//
//	/**
//	 Get the cached pow10 value from `pow10_sig_table`.
//	 @param exp10 The exponent of pow(10, e). This value must in range
//	              `POW10_SIG_TABLE_MIN_EXP` to `POW10_SIG_TABLE_MAX_EXP`.
//	 @param hi    The highest 64 bits of pow(10, e).
//	 @param lo    The lower 64 bits after `hi`.
//	 */
//go:nocheckptr
func pow10_table_get_sig(tls *libc.TLS, exp10 Ti32, hi uintptr, lo uintptr) {
	var idx Ti32
	_ = idx
	idx = exp10 - -int32(343)
	*(*Tu64)(unsafe.Pointer(hi)) = pow10_sig_table[idx*int32(2)]
	*(*Tu64)(unsafe.Pointer(lo)) = pow10_sig_table[idx*int32(2)+int32(1)]
}

// C documentation
//
//	/**
//	 Get the exponent (base 2) for highest 64 bits significand in `pow10_sig_table`.
//	 */
//go:nocheckptr
func pow10_table_get_exp(tls *libc.TLS, exp10 Ti32, exp2 uintptr) {
	/* e2 = floor(log2(pow(10, e))) - 64 + 1 */
	/*    = floor(e * log2(10) - 63)         */
	*(*Ti32)(unsafe.Pointer(exp2)) = (exp10*int32(217706) - int32(4128768)) >> int32(16)
}

