func write_u64(tls *libc.TLS, val Tu64, buf uintptr) (r uintptr) {
	var hgh, tmp Tu64
	var low, mid Tu32
	_, _, _, _ = hgh, low, mid, tmp
	if val < uint64(100000000) { /* 1-8 digits */
		buf = write_u32_len_1_to_8(tls, uint32(val), buf)
		return buf
	} else {
		if val < libc.Uint64FromInt32(100000000)*libc.Uint64FromInt32(100000000) { /* 9-16 digits */
			hgh = val / uint64(100000000)                           /* (val / 100000000) */
			low = uint32(val - hgh*libc.Uint64FromInt32(100000000)) /* (val % 100000000) */
			buf = write_u32_len_1_to_8(tls, uint32(hgh), buf)
			buf = write_u32_len_8(tls, low, buf)
			return buf
		} else { /* 17-20 digits */
			tmp = val / uint64(100000000)                           /* (val / 100000000) */
			low = uint32(val - tmp*libc.Uint64FromInt32(100000000)) /* (val % 100000000) */
			hgh = uint64(uint32(tmp / libc.Uint64FromInt32(10000))) /* (tmp / 10000) */
			mid = uint32(tmp - hgh*libc.Uint64FromInt32(10000))     /* (tmp % 10000) */
			buf = write_u32_len_5_to_8(tls, uint32(hgh), buf)
			buf = write_u32_len_4(tls, mid, buf)
			buf = write_u32_len_8(tls, low, buf)
			return buf
		}
	}
	return r
}

