// C documentation
//
//	/** Trailing zero count table for number 0 to 99.
//	    (generate with misc/make_tables.c) */
var dec_trailing_zero_table = [100]Tu8{
	0:  uint8(2),
	10: uint8(1),
	20: uint8(1),
	30: uint8(1),
	40: uint8(1),
	50: uint8(1),
	60: uint8(1),
	70: uint8(1),
	80: uint8(1),
	90: uint8(1),
}

func write_u64_len_1_to_16(tls *libc.TLS, val Tu64, buf uintptr) (r uintptr) {
	var hgh Tu64
	var low Tu32
	_, _ = hgh, low
	if val < uint64(100000000) { /* 1-8 digits */
		buf = write_u32_len_1_to_8(tls, uint32(val), buf)
		return buf
	} else { /* 9-16 digits */
		hgh = val / uint64(100000000)                           /* (val / 100000000) */
		low = uint32(val - hgh*libc.Uint64FromInt32(100000000)) /* (val % 100000000) */
		buf = write_u32_len_1_to_8(tls, uint32(hgh), buf)
		buf = write_u32_len_8(tls, low, buf)
		return buf
	}
	return r
}

//go:nocheckptr
func write_u64_len_1_to_17(tls *libc.TLS, val Tu64, buf uintptr) (r uintptr) {
	var hgh Tu64
	var low, mid, one Tu32
	_, _, _, _ = hgh, low, mid, one
	if val >= libc.Uint64FromInt32(100000000)*libc.Uint64FromInt32(10000000) { /* len: 16 to 17 */
		hgh = val / uint64(100000000)                                   /* (val / 100000000) */
		low = uint32(val - hgh*libc.Uint64FromInt32(100000000))         /* (val % 100000000) */
		one = uint32(hgh / libc.Uint64FromInt32(100000000))             /* (hgh / 100000000) */
		mid = uint32(hgh - uint64(one)*libc.Uint64FromInt32(100000000)) /* (hgh % 100000000) */
		*(*Tu8)(unsafe.Pointer(buf)) = libc.Uint8FromInt32(libc.Int32FromUint8(uint8(one)) + libc.Int32FromUint8(libc.Uint8FromUint8('0')))
		buf = buf + libc.BoolUintptr(one > uint32(0))
		buf = write_u32_len_8(tls, mid, buf)
		buf = write_u32_len_8(tls, low, buf)
		return buf
	} else {
		if val >= libc.Uint64FromInt32(100000000) { /* len: 9 to 15 */
			hgh = val / uint64(100000000)                           /* (val / 100000000) */
			low = uint32(val - hgh*libc.Uint64FromInt32(100000000)) /* (val % 100000000) */
			buf = write_u32_len_1_to_8(tls, uint32(hgh), buf)
			buf = write_u32_len_8(tls, low, buf)
			return buf
		} else { /* len: 1 to 8 */
			buf = write_u32_len_1_to_8(tls, uint32(val), buf)
			return buf
		}
	}
	return r
}

// C documentation
//
//	/**
//	 Write an unsigned integer with a length of 7 to 9 with trailing zero trimmed.
//	 These digits are named as "abbccddee" here.
//	 For example, input 123456000, output "123456".
//	 */
//go:nocheckptr
func write_u32_len_7_to_9_trim(tls *libc.TLS, val Tu32, buf uintptr) (r uintptr) {
	var a, abb, abbcc, bb, cc, dd, ddee, ee, tz, tz1, tz2 Tu32
	var lz uint8
	var v1 uint32
	_, _, _, _, _, _, _, _, _, _, _, _, _ = a, abb, abbcc, bb, cc, dd, ddee, ee, lz, tz, tz1, tz2, v1
	abbcc = val / uint32(10000)                                                           /* (abbccddee / 10000) */
	ddee = val - abbcc*uint32(10000)                                                      /* (abbccddee % 10000) */
	abb = uint32(uint64(abbcc) * libc.Uint64FromInt32(167773) >> libc.Int32FromInt32(24)) /* (abbcc / 100) */
	a = abb * uint32(41) >> int32(12)                                                     /* (abb / 100) */
	bb = abb - a*uint32(100)                                                              /* (abb % 100) */
	cc = abbcc - abb*uint32(100)                                                          /* (abbcc % 100) */
	/* write abbcc */
	*(*Tu8)(unsafe.Pointer(buf)) = uint8(a + libc.Uint32FromUint8('0'))
	buf = buf + libc.BoolUintptr(a > uint32(0))
	lz = libc.BoolUint8(bb < uint32(10) && a == uint32(0))
	byte_copy_2(tls, buf+uintptr(0), uintptr(unsafe.Pointer(&digit_table))+uintptr(bb*uint32(2))+uintptr(lz))
	buf = buf - uintptr(lz)
	byte_copy_2(tls, buf+uintptr(2), uintptr(unsafe.Pointer(&digit_table))+uintptr(cc*uint32(2)))
	if ddee != 0 {
		dd = ddee * uint32(5243) >> int32(19) /* (ddee / 100) */
		ee = ddee - dd*uint32(100)            /* (ddee % 100) */
		byte_copy_2(tls, buf+uintptr(4), uintptr(unsafe.Pointer(&digit_table))+uintptr(dd*uint32(2)))
		byte_copy_2(tls, buf+uintptr(6), uintptr(unsafe.Pointer(&digit_table))+uintptr(ee*uint32(2)))
		tz1 = uint32(dec_trailing_zero_table[dd])
		tz2 = uint32(dec_trailing_zero_table[ee])
		if ee != 0 {
			v1 = tz2
		} else {
			v1 = tz1 + uint32(2)
		}
		tz = v1
		buf = buf + uintptr(uint32(8)-tz)
		return buf
	} else {
		tz1 = uint32(dec_trailing_zero_table[bb])
		tz2 = uint32(dec_trailing_zero_table[cc])
		if cc != 0 {
			v1 = tz2
		} else {
			v1 = tz1 + tz2
		}
		tz = v1
		buf = buf + uintptr(uint32(4)-tz)
		return buf
	}
	return r
}

// C documentation
//
//	/**
//	 Write an unsigned integer with a length of 16 or 17 with trailing zero trimmed.
//	 These digits are named as "abbccddeeffgghhii" here.
