// C documentation
//
//	/** Returns the encode table with options. */
//go:nocheckptr
func get_enc_table_with_flag(tls *libc.TLS, flg Tyyjson_write_flag) (r uintptr) {
	if libc.BoolInt64(!!(has_wflag(tls, flg, YYJSON_WRITE_ESCAPE_UNICODE, libc.BoolUint8(0 != 0)) != 0)) != 0 {
		if libc.BoolInt64(!!(has_wflag(tls, flg, YYJSON_WRITE_ESCAPE_SLASHES, libc.BoolUint8(0 != 0)) != 0)) != 0 {
			return uintptr(unsafe.Pointer(&enc_table_esc_slash))
		} else {
			return uintptr(unsafe.Pointer(&enc_table_esc))
		}
	} else {
		if libc.BoolInt64(!!(has_wflag(tls, flg, YYJSON_WRITE_ESCAPE_SLASHES, libc.BoolUint8(0 != 0)) != 0)) != 0 {
			return uintptr(unsafe.Pointer(&enc_table_cpy_slash))
		} else {
			return uintptr(unsafe.Pointer(&enc_table_cpy))
		}
	}
	return r
}

// C documentation
//
//	/** Write raw string. */
func write_raw(tls *libc.TLS, cur uintptr, raw uintptr, raw_len Tusize) (r uintptr) {
	libc.Xmemcpy(tls, cur, raw, raw_len)
	return cur + uintptr(raw_len)
}

